'use client';

import { useRef, useState } from 'react';
import { ArrowUpRight, ChevronRight, X } from 'lucide-react';
import {
  BgFolderVector,
  DashboardFolderPlusIcon,
  DashboardImagesIcon,
  DashboardVideoIcon,
  FigGraduationIcon,
  FigLightbulbIcon,
  FigPlayIcon,
  FigSparkleIcon,
  InspireFourIcon,
  InspireOneIcon,
  InspireThreeIcon,
  InspireTwoIcon,
} from '../../assets/icons';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';

const dashboardActions = [
  {
    title: 'Create a Demostack',
    description: 'Record an example Demostack in under 2 minutes',
    image: 'https://assets.watermelon.sh/components/bg-element-wave.webp',
    icon: DashboardFolderPlusIcon,
  },
  {
    title: 'Interactive Tutorial',
    description: 'Get a high-level platform overview in a few clicks',
    image: 'https://assets.watermelon.sh/components/bg-element-neon.webp',
    icon: DashboardVideoIcon,
  },
  {
    title: 'Explore Gallery',
    description: 'Get inspired with examples and use cases',
    image: 'https://assets.watermelon.sh/components/bg-element-sky.webp',
    icon: DashboardImagesIcon,
  },
] as const;

const dashboardTips = [
  {
    title: 'Use case tips from the CEO',
    description: 'Our high-level recommendation',
    image: 'https://assets.watermelon.sh/components/demostack-tip-1.webp',
  },
  {
    title: 'Personalized outbound',
    description: 'Use variables to send personalized demos at scale',
    image: 'https://assets.watermelon.sh/components/demostack-tip-2.webp',
  },
  {
    title: 'Tradeshow and expo demos',
    description: 'Include in email sequences or follow-ups',
    image: 'https://assets.watermelon.sh/components/demostack-tip-3.webp',
  },
  {
    title: 'Modular onboarding emails',
    description: 'Include in email sequences or follow-ups',
    image: 'https://assets.watermelon.sh/components/demostack-tip-4.webp',
  },
] as const;

const inspiredDemos = [
  { title: 'Mobile App Demo', icon: InspireOneIcon },
  { title: 'Payment Flow Demo', icon: InspireTwoIcon },
  { title: 'Team Workspace Demo', icon: InspireThreeIcon },
  { title: 'Analytics Platform Demo', icon: InspireFourIcon },
] as const;

const dashboardResources = [
  { label: 'Learning Academy', icon: FigGraduationIcon },
  { label: 'Knowledge Base', icon: FigLightbulbIcon },
  { label: 'How we use Demostack', icon: FigPlayIcon },
  { label: 'Product Updates', icon: FigSparkleIcon },
] as const;

export function DashboardContent() {
  return (
    <div className="mx-auto w-full max-w-6xl space-y-9 px-4 py-6 sm:p-7">
      <section className="grid grid-cols-1 gap-4 md:grid-cols-3">
        {dashboardActions.map((action) => (
          <DashboardActionCard key={action.title} action={action} />
        ))}
      </section>

      <DashboardTips />

      <div className="flex flex-col gap-8 lg:flex-row">
        <ResourcesSection />
        <InspirationList />
      </div>
    </div>
  );
}

function DashboardActionCard({
  action,
}: {
  action: (typeof dashboardActions)[number];
}) {
  const Icon = action.icon;

  return (
    <Card className="shadow-border hover:shadow-border-hover gap-8 rounded-2xl py-4 ring-0 transition-[transform,box-shadow] duration-200 ease-out hover:-translate-y-0.5 motion-reduce:transform-none">
      <CardContent className="flex flex-col items-start gap-8">
        <div className="relative flex size-11 items-center justify-center overflow-hidden rounded-lg">
          <img
            src={action.image}
            alt=""
            width={44}
            height={44}
            className="absolute inset-0 size-full object-cover"
          />
          <Icon className="text-primary-foreground relative z-10 size-6" />
        </div>
        <div className="flex w-full flex-col gap-1">
          <p className="font-medium">{action.title}</p>
          <p className="text-muted-foreground text-sm">{action.description}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function DashboardTips() {
  const [visible, setVisible] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  if (!visible) {
    return null;
  }

  function scrollRight() {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({
        left: scrollRef.current.clientWidth,
        behavior: 'smooth',
      });
    }
  }

  return (
    <section className="flex flex-col gap-8">
      <div className="flex items-center justify-between">
        <div className="flex flex-col gap-2">
          <h2 className="text-lg font-semibold">Demostack Tips</h2>
          <p className="text-muted-foreground">
            Drive successful outcomes across multiple departments and
            interactive demos
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setVisible(false)}
          className="bg-card shadow-border rounded-full border-0"
          aria-label="Close tips"
        >
          Close
          <X />
        </Button>
      </div>

      <div className="relative overflow-hidden">
        <div
          ref={scrollRef}
          className="flex gap-6 overflow-x-auto scroll-smooth pb-2"
        >
          {dashboardTips.map((tip) => (
            <article
              key={tip.title}
              className="flex w-64 shrink-0 flex-col items-start gap-4"
            >
              <div className="relative aspect-[3/2] w-64 overflow-hidden rounded-2xl">
                <img
                  src={tip.image}
                  alt=""
                  width={256}
                  height={176}
                  className="size-full object-cover"
                />
              </div>
              <div className="flex w-full flex-col gap-1">
                <h3 className="font-medium">{tip.title}</h3>
                <p className="text-muted-foreground text-sm">
                  {tip.description}
                </p>
              </div>
            </article>
          ))}
        </div>

        <div className="from-background via-background/70 absolute top-0 right-0 h-64 w-36 bg-gradient-to-l to-transparent" />
        <Button
          variant="outline"
          size="icon-lg"
          onClick={scrollRight}
          className="bg-card shadow-border absolute top-28 right-0 z-10 rounded-full border-0"
          aria-label="Show more tips"
        >
          <ChevronRight className="size-5" />
        </Button>
      </div>
    </section>
  );
}

function ResourcesSection() {
  return (
    <section className="flex flex-1 flex-col items-start gap-8 lg:max-w-lg">
      <h2 className="text-lg font-semibold">Resources</h2>
      <div className="grid w-full grid-cols-2 gap-4">
        {dashboardResources.map((resource) => {
          const Icon = resource.icon;

          return (
            <article
              key={resource.label}
              className="group flex flex-col items-start gap-3"
            >
              <div className="bg-muted shadow-border group-hover:shadow-border-hover flex h-32 w-full items-center justify-center overflow-hidden rounded-xl transition-[transform,box-shadow] duration-200 ease-out group-hover:-translate-y-0.5 motion-reduce:transform-none">
                <div className="relative flex size-20 items-center justify-center transition-transform duration-200 ease-out group-hover:-translate-y-1 group-hover:rotate-1 motion-reduce:transform-none">
                  <BgFolderVector className="absolute inset-0 size-full" />
                  <Icon className="relative z-10 mt-4 size-6 transition-transform duration-200 ease-out group-hover:scale-110 motion-reduce:transform-none" />
                </div>
              </div>
              <h3 className="font-medium transition-transform duration-200 ease-out group-hover:translate-x-0.5 motion-reduce:transform-none">
                {resource.label}
              </h3>
            </article>
          );
        })}
      </div>
    </section>
  );
}

function InspirationList() {
  return (
    <section className="flex flex-1 flex-col items-start gap-8">
      <h2 className="text-lg font-semibold">Get Inspired</h2>
      <div className="flex w-full flex-col gap-2">
        {inspiredDemos.map((item) => {
          const Icon = item.icon;

          return (
            <article
              key={item.title}
              className="bg-muted shadow-border hover:shadow-border-hover group flex h-18 w-full items-center justify-between rounded-2xl py-4 pr-8 pl-6 transition-[transform,box-shadow] duration-200 ease-out hover:-translate-y-0.5 motion-reduce:transform-none"
            >
              <div className="flex items-center gap-4">
                <div className="flex size-8 shrink-0 items-center justify-center">
                  <Icon className="max-h-7 max-w-7 transition-transform duration-200 ease-out group-hover:scale-105 motion-reduce:transform-none" />
                </div>
                <h3 className="font-medium">{item.title}</h3>
              </div>
              <ArrowUpRight className="text-muted-foreground size-6 transition-transform duration-200 ease-out group-hover:translate-x-1 group-hover:-translate-y-1 motion-reduce:transform-none" />
            </article>
          );
        })}
      </div>
    </section>
  );
}

'use client';

import { useMemo, useState, type ReactNode } from 'react';
import {
  Archive,
  ArrowDownWideNarrow,
  Copy,
  EllipsisVertical,
  ExternalLink,
  Filter,
  FolderInput,
  FolderPlus,
  Grid2X2,
  Info,
  List,
  Pencil,
  Plus,
  Trash2,
  UserRound,
  Users,
} from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Button, buttonVariants } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { demostacks, type Demostack } from '../../data';

const demostackAuthors = [
  ...new Set(demostacks.map((demostack) => demostack.author)),
];

const sortLabels = {
  recent: 'Recent',
  ascending: 'Title A-Z',
  descending: 'Title Z-A',
} as const;

type SortMode = keyof typeof sortLabels;
type ViewMode = 'grid' | 'list';

function getInitials(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .map((part) => part[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);
}

export function DemostacksContent() {
  const [sort, setSort] = useState<SortMode>('recent');
  const [selectedAuthors, setSelectedAuthors] = useState<string[]>([]);
  const [view, setView] = useState<ViewMode>('grid');

  const visibleDemostacks = useMemo(() => {
    const filtered = selectedAuthors.length
      ? demostacks.filter((demostack) =>
          selectedAuthors.includes(demostack.author),
        )
      : demostacks;

    if (sort === 'ascending') {
      return [...filtered].sort((a, b) => a.title.localeCompare(b.title));
    }
    if (sort === 'descending') {
      return [...filtered].sort((a, b) => b.title.localeCompare(a.title));
    }
    return filtered;
  }, [selectedAuthors, sort]);

  return (
    <TooltipProvider>
      <Tabs defaultValue="demostacks" className="min-w-0">
        <main className="w-full min-w-0 px-4 py-6 sm:p-7">
          <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-semibold">Team Demostacks</h2>
              <Tooltip>
                <TooltipTrigger
                  className={buttonVariants({
                    variant: 'ghost',
                    size: 'icon-xs',
                    className: 'text-muted-foreground rounded-full',
                  })}
                  aria-label="About Team Demostacks"
                >
                  <Info className="size-4" />
                </TooltipTrigger>
                <TooltipContent>
                  Demostacks shared with everyone in your workspace
                </TooltipContent>
              </Tooltip>
            </div>

            <div className="flex w-full flex-wrap items-center justify-between gap-3 sm:w-auto sm:flex-nowrap sm:justify-start sm:gap-4">
              <TabsList className="shadow-border h-10! gap-0 rounded-xl">
                <PrimaryTab value="demostacks">Demostacks</PrimaryTab>
                <PrimaryTab value="screenshots">Screenshots</PrimaryTab>
              </TabsList>
              <DropdownMenu>
                <DropdownMenuTrigger
                  className={buttonVariants({
                    size: 'lg',
                    className: 'shadow-primary rounded-xl',
                  })}
                >
                  Create
                  <Plus className="size-5" />
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-48">
                  <DropdownMenuItem>
                    <Plus />
                    New Demostack
                  </DropdownMenuItem>
                  <DropdownMenuItem>
                    <Plus />
                    New Screenshot
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>

          <TabsContent value="demostacks">
            <Tabs
              defaultValue="shared"
              className="mt-8 min-w-0 gap-6 sm:mt-10 sm:gap-8"
            >
              <DemostacksToolbar
                sort={sort}
                setSort={setSort}
                selectedAuthors={selectedAuthors}
                setSelectedAuthors={setSelectedAuthors}
                view={view}
                setView={setView}
              />
              <TabsContent value="shared">
                <DemostackCollection demos={visibleDemostacks} view={view} />
              </TabsContent>
              <TabsContent value="personal">
                <EmptyState
                  title="No personal Demostacks yet"
                  description="Demostacks visible only to you will appear here."
                />
              </TabsContent>
              <TabsContent value="archive">
                <EmptyState
                  title="Archive is empty"
                  description="Archived Demostacks will appear here."
                />
              </TabsContent>
            </Tabs>
          </TabsContent>
          <TabsContent value="screenshots">
            <EmptyState
              title="No screenshots yet"
              description="Create a screenshot to see it in this workspace."
              className="mt-10"
            />
          </TabsContent>
        </main>
      </Tabs>
    </TooltipProvider>
  );
}

function PrimaryTab({
  value,
  children,
}: {
  value: string;
  children: ReactNode;
}) {
  return (
    <TabsTrigger
      value={value}
      className="data-active:bg-primary/10 data-active:text-primary data-[state=active]:bg-primary/10 data-[state=active]:text-primary flex-none rounded-lg px-3 data-active:shadow-none! data-[state=active]:shadow-none!"
    >
      {children}
    </TabsTrigger>
  );
}

type DemostacksToolbarProps = {
  sort: SortMode;
  setSort: (sort: SortMode) => void;
  selectedAuthors: string[];
  setSelectedAuthors: (authors: string[]) => void;
  view: ViewMode;
  setView: (view: ViewMode) => void;
};

function DemostacksToolbar({
  sort,
  setSort,
  selectedAuthors,
  setSelectedAuthors,
  view,
  setView,
}: DemostacksToolbarProps) {
  function toggleAuthor(author: string, checked: boolean) {
    setSelectedAuthors(
      checked
        ? [...selectedAuthors, author]
        : selectedAuthors.filter((item) => item !== author),
    );
  }

  return (
    <div className="flex min-w-0 flex-col gap-4 border-b lg:flex-row lg:items-end lg:justify-between">
      <TabsList variant="line">
        <WorkspaceTab value="shared" icon={Users}>
          <span className="sm:hidden">Team</span>
          <span className="hidden sm:inline">Shared with Team</span>
        </WorkspaceTab>
        <WorkspaceTab value="personal" icon={UserRound}>
          Personal
        </WorkspaceTab>
        <WorkspaceTab value="archive" icon={Archive}>
          Archive
        </WorkspaceTab>
      </TabsList>

      <div className="flex w-full flex-wrap items-center gap-2 pb-3 lg:w-auto lg:gap-3 lg:pb-2">
        <DropdownMenu>
          <DropdownMenuTrigger
            className={buttonVariants({
              variant: 'outline',
              size: 'lg',
              className:
                'bg-card text-muted-foreground shadow-border mr-auto rounded-xl border-0',
            })}
          >
            <ArrowDownWideNarrow className="size-5" />
            {sortLabels[sort]}
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48">
            <DropdownMenuRadioGroup
              value={sort}
              onValueChange={(value) => setSort(value as SortMode)}
            >
              <DropdownMenuLabel>Sort by</DropdownMenuLabel>
              {Object.entries(sortLabels).map(([value, label]) => (
                <DropdownMenuRadioItem key={value} value={value}>
                  {label}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger
            className={buttonVariants({
              variant: 'outline',
              size: 'lg',
              className: cn(
                'bg-card text-muted-foreground shadow-border rounded-xl border-0',
                selectedAuthors.length && 'bg-muted',
              ),
            })}
            aria-label="Filter by creator"
          >
            <Filter className="size-5" />
            <span className="hidden sm:inline">Filter</span>
            {selectedAuthors.length > 0 && (
              <span className="bg-primary text-primary-foreground flex size-5 items-center justify-center rounded-full text-xs">
                {selectedAuthors.length}
              </span>
            )}
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-52">
            <DropdownMenuGroup>
              <DropdownMenuLabel>Filter by creator</DropdownMenuLabel>
              {demostackAuthors.map((author) => (
                <DropdownMenuCheckboxItem
                  key={author}
                  checked={selectedAuthors.includes(author)}
                  onCheckedChange={(checked) => toggleAuthor(author, checked)}
                >
                  {author}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuGroup>
            {selectedAuthors.length > 0 && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => setSelectedAuthors([])}>
                  Clear filters
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger
            className={buttonVariants({
              variant: 'outline',
              size: 'icon-lg',
              className:
                'bg-card text-muted-foreground shadow-border rounded-xl border-0',
            })}
            aria-label="Folder options"
          >
            <FolderPlus className="size-5" />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-44">
            <DropdownMenuItem>
              <FolderPlus />
              New folder
            </DropdownMenuItem>
            <DropdownMenuItem>
              <FolderInput />
              Manage folders
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <Button
          variant="outline"
          size="icon-lg"
          className={cn(
            'bg-card text-muted-foreground shadow-border rounded-xl border-0',
            view === 'list' && 'bg-muted',
          )}
          aria-label={view === 'grid' ? 'Use list view' : 'Use grid view'}
          onClick={() => setView(view === 'grid' ? 'list' : 'grid')}
        >
          {view === 'grid' ? (
            <List className="size-5" />
          ) : (
            <Grid2X2 className="size-5" />
          )}
        </Button>
      </div>
    </div>
  );
}

function WorkspaceTab({
  value,
  icon: Icon,
  children,
}: {
  value: string;
  icon: typeof Users;
  children: ReactNode;
}) {
  return (
    <TabsTrigger
      value={value}
      className="data-active:text-primary data-active:after:bg-primary data-[state=active]:text-primary data-[state=active]:after:bg-primary px-2 text-sm sm:px-4 sm:text-base"
    >
      <Icon className="size-4 sm:size-5" />
      {children}
    </TabsTrigger>
  );
}

function DemostackCollection({
  demos,
  view,
}: {
  demos: Demostack[];
  view: ViewMode;
}) {
  if (!demos.length) {
    return (
      <EmptyState
        title="No matching Demostacks"
        description="Clear or change the active creator filters."
      />
    );
  }

  return (
    <section
      className={cn(
        view === 'grid'
          ? 'grid grid-cols-1 gap-6 sm:grid-cols-2 xl:grid-cols-4'
          : 'space-y-3',
      )}
    >
      {demos.map((demostack) => (
        <article
          key={demostack.id}
          className={cn(
            'group min-w-0 cursor-pointer',
            view === 'list' &&
              'hover:bg-muted/40 flex w-full max-w-full items-center gap-3 overflow-hidden rounded-2xl border p-3 transition sm:gap-4',
          )}
        >
          <div
            className={cn(
              'relative aspect-video overflow-hidden rounded-2xl border',
              view === 'list' && 'w-2/5 max-w-44 shrink-0',
            )}
          >
            <img
              src={demostack.image}
              alt=""
              width={1280}
              height={720}
              className="size-full object-cover motion-safe:transition-transform motion-safe:duration-300 motion-safe:group-hover:scale-105"
            />
          </div>

          <div
            className={cn(
              'min-w-0 space-y-2',
              view === 'grid' ? 'mt-4' : 'flex-1',
            )}
          >
            <div className="flex items-center justify-between gap-3">
              <div className="min-w-0 flex-1">
                <h3 className="group-hover:text-primary truncate font-medium transition-colors">
                  {demostack.title}
                </h3>
              </div>
              <CardMenu title={demostack.title} />
            </div>
            <div className="text-muted-foreground flex min-w-0 items-center gap-2 text-xs">
              <Avatar size="sm" className="shrink-0">
                <AvatarImage src={demostack.avatar} alt={demostack.author} />
                <AvatarFallback>{getInitials(demostack.author)}</AvatarFallback>
              </Avatar>
              <span className="truncate">{demostack.author}</span>
              <span aria-hidden>·</span>
              <time className="shrink-0" dateTime="2026-03-02">
                Mar 02
              </time>
            </div>
          </div>
        </article>
      ))}
    </section>
  );
}

function CardMenu({ title }: { title: string }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        className={buttonVariants({
          variant: 'ghost',
          size: 'icon-xs',
          className: 'text-muted-foreground rounded-full',
        })}
        aria-label={`More options for ${title}`}
      >
        <EllipsisVertical className="size-4" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuItem>
          <ExternalLink />
          Open
        </DropdownMenuItem>
        <DropdownMenuItem>
          <Pencil />
          Rename
        </DropdownMenuItem>
        <DropdownMenuItem>
          <Copy />
          Duplicate
        </DropdownMenuItem>
        <DropdownMenuItem>
          <FolderInput />
          Move to folder
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <Archive />
          Archive
        </DropdownMenuItem>
        <DropdownMenuItem variant="destructive">
          <Trash2 />
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function EmptyState({
  title,
  description,
  className,
}: {
  title: string;
  description: string;
  className?: string;
}) {
  return (
    <div
      className={cn(
        'bg-muted/40 flex min-h-64 flex-col items-center justify-center gap-2 rounded-2xl border border-dashed px-6 text-center',
        className,
      )}
    >
      <p className="font-medium">{title}</p>
      <p className="text-muted-foreground text-sm">{description}</p>
    </div>
  );
}

'use client';

import { type CSSProperties, useEffect, useState } from 'react';
import {
  Blocks,
  ChevronDown,
  ChevronsLeft,
  LogOut,
  Moon,
  Settings,
  Sun,
  User,
} from 'lucide-react';
import { BuildingIcon, CaretUpDownIcon } from '../../assets/icons';
import { DemostackLogo } from '../../assets/logo';
import { SidebarNavigationItem } from './sidebar-navigation-item';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
