            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          {searchQuery === '' && (
            <InputGroupAddon
              align="inline-end"
              className="hidden pr-1.5 md:flex"
            >
              <div className="text-muted-foreground bg-card flex h-6 w-9 items-center justify-center gap-1 rounded-md border">
